'use strict';
// Manual slots are independent of the existing automatic save.
class RingSaveSlots{
 constructor(storage,validate){this.storage=storage;this.validate=validate;this.key='project-ring-manual-slots-v1'}
 read(){let raw;try{raw=this.storage.getItem(this.key)}catch{throw Error('저장소를 열 수 없습니다.')}if(raw===null)return Array(5).fill(null);let data;try{data=JSON.parse(raw)}catch{throw Error('슬롯 데이터를 읽을 수 없어 원본을 보존했습니다.')}if(data?.version!==1||!Array.isArray(data.slots)||data.slots.length!==5)throw Error('슬롯 데이터를 읽을 수 없어 원본을 보존했습니다.');return data.slots}
 get(index){if(!Number.isInteger(index)||index<0||index>4)throw Error('슬롯을 선택해 주세요.');const slot=this.read()[index];if(slot&&(!Number.isFinite(Date.parse(slot.savedAt))||!this.validate(slot.state)))throw Error('이 슬롯의 저장 데이터를 읽을 수 없습니다.');return slot}
 put(index,state){if(!Number.isInteger(index)||index<0||index>4||!this.validate(state))throw Error('현재 진행을 저장할 수 없습니다.');const slots=this.read();const snapshot=JSON.parse(JSON.stringify(state));slots[index]={savedAt:new Date().toISOString(),state:snapshot};try{this.storage.setItem(this.key,JSON.stringify({version:1,slots}))}catch{throw Error('저장 공간이 부족하거나 브라우저가 저장을 차단했습니다.')}return slots[index]}
}
window.RingSaveSlots=RingSaveSlots;
window.RingTitle=(()=>{
 let api=null,store=null,visible=true,panel=null,ready=false,loading=false,inSession=false,settings={music:true,musicVolume:.35},lastFocus=null;
 const $=s=>document.querySelector(s),audio=new Audio('assets/title-inst.mp3'),gameAudio=new Audio('assets/cafe-jazz.mp3');for(const track of [audio,gameAudio]){track.loop=true;track.preload='auto'}
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 try{const saved=JSON.parse(localStorage.getItem('project-ring-title-settings-v1')||'null');if(saved&&typeof saved.music==='boolean'&&Number.isFinite(saved.musicVolume))settings={music:saved.music,musicVolume:Math.min(1,Math.max(0,saved.musicVolume))}}catch{}
 function persistSettings(){try{localStorage.setItem('project-ring-title-settings-v1',JSON.stringify(settings))}catch{}}
 function playMusic(){const active=visible?audio:gameAudio,other=visible?gameAudio:audio;other.pause();active.volume=settings.musicVolume;if((visible||inSession)&&panel!=='exit'&&settings.music&&settings.musicVolume>0&&!document.hidden){const p=active.play();p?.catch(()=>{})}else active.pause()}
 function message(text){const node=$('#titleFeedback');if(node)node.textContent=text}
 function setBlocked(){document.body.classList.toggle('title-active',visible);$('#titleScreen').inert=!!panel;$('#titleScreen').hidden=!visible;$('#app').inert=visible||!!panel;const modal=$('#modal');if(modal)modal.inert=visible||!!panel;$('#titleMusic').textContent=settings.music?'♪ 음악 켜짐':'♪ 음악 꺼짐';$('#titleMusic').setAttribute('aria-pressed',!settings.music);playMusic()}
 async function prepare(){
  if(ready)return true;if(loading)return false;loading=true;
  const button=$('#titleRetry');if(button)button.hidden=true;
  try{await window.RingAssets.ensure((n,total)=>{const p=$('#titleLoad');p.textContent=n===total?'준비 완료':`장면 준비 중 ${Math.round(n/total*100)}%`;$('#titleLoadBar').style.width=n/total*100+'%'});ready=true;$('#titleLoad').textContent='';$('#titleLoading').hidden=true;document.querySelectorAll('[data-title-action="start"],[data-title-action="continue"]').forEach(b=>b.disabled=b.dataset.titleAction==='continue'&&!api.hasProgress());return true}catch{message('장면을 불러오지 못했습니다. 다시 시도해 주세요.');if(button)button.hidden=false;return false}finally{loading=false}
 }
 function closePanel(){const restore=lastFocus;$('#titlePanel').hidden=true;$('#titlePanelContent').innerHTML='';panel=null;setBlocked();if(!visible)api.resumeView();restore?.focus?.({preventScroll:true})}
 function showPanel(kind,title,html){lastFocus=document.activeElement;panel=kind;api.pause();$('#titlePanel').hidden=false;$('#titlePanelContent').innerHTML=`<div class="title-panel-heading"><h2>${title}</h2><button id="titlePanelClose" aria-label="창 닫기">×</button></div>${html}<p id="titleFeedback" role="status"></p>`;$('#titlePanelClose').onclick=closePanel;setBlocked();$('#titlePanelClose').focus()}
 function confirmAction(title,text,action){showPanel('confirm',title,`<p class="title-confirm-copy">${text}</p><div class="title-panel-actions"><button id="titleCancel">취소</button><button id="titleConfirm" class="primary">확인</button></div>`);$('#titleCancel').onclick=closePanel;$('#titleConfirm').onclick=action}
 function slotView(mode){
  let slots;try{slots=store.read()}catch(error){showPanel('slots',mode==='save'?'저장':'불러오기',`<p>${esc(error.message)}</p>`);return}
  const rows=slots.map((entry,index)=>{let slot,corrupt=false;try{slot=store.get(index)}catch{corrupt=true}const state=slot?.state;const date=slot?new Intl.DateTimeFormat('ko-KR',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Seoul'}).format(new Date(slot.savedAt)):'';
   return `<button class="save-slot ${slot?'occupied':''}" data-slot="${index}" ${mode==='load'&&(!slot||corrupt)||mode==='save'&&(!api.hasProgress()||corrupt)?'disabled':''}><span class="slot-number">${String(index+1).padStart(2,'0')}</span><span class="slot-preview" aria-hidden="true"></span><span class="slot-copy"><strong>${corrupt?'읽을 수 없는 데이터':slot?'DAY '+state.day+' · ¥'+state.money.toLocaleString():'비어 있는 슬롯'}</strong><span>${slot?esc(api.describe(state)):mode==='save'?'이곳에 현재 진행 저장':'저장된 진행 없음'}</span><small>${date}</small></span><span class="slot-command">${mode==='save'?'저장':'불러오기'}</span></button>`}).join('');
  showPanel('slots',mode==='save'?'진행 저장':'진행 불러오기',`<p class="slot-intro">자동 저장과 별도로 5개의 슬롯을 사용할 수 있습니다.</p><div class="save-slot-list">${rows}</div>`);
  document.querySelectorAll('[data-slot]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.slot);if(mode==='save'){
   const write=()=>{try{store.put(index,api.snapshot());slotView('save');message((index+1)+'번 슬롯에 저장했습니다.');api.beep('choice')}catch(error){message(error.message)}};
   if(slots[index])confirmAction('슬롯 '+(index+1)+' 덮어쓰기','이 슬롯의 진행을 현재 진행으로 바꿀까요?',write);else write();
  }else confirmAction('슬롯 '+(index+1)+' 불러오기','선택한 진행으로 돌아갑니다. 현재 진행을 보관하려면 먼저 다른 슬롯에 저장해 주세요.',async()=>{const confirmButton=$('#titleConfirm');if(confirmButton)confirmButton.disabled=true;try{if(!ready){message('장면을 준비하고 있습니다…');await window.RingAssets.ensure();ready=true}const slot=store.get(index);if(!slot)throw Error('비어 있는 슬롯입니다.');api.load(slot.state)}catch(error){message(error.message)}finally{if(confirmButton?.isConnected)confirmButton.disabled=false}})});
 }
 function showSettings(){
  const s=api.snapshot();showPanel('settings','설정',`<label class="title-option"><span>배경 음악</span><input id="titleBgmEnabled" type="checkbox" ${settings.music?'checked':''}></label><label class="title-option"><span>음악 크기</span><input id="titleBgmVolume" type="range" min="0" max="100" value="${Math.round(settings.musicVolume*100)}"></label><label class="title-option"><span>효과음</span><input id="titleSfxEnabled" type="checkbox" ${s.sound?'checked':''}></label><label class="title-option"><span>효과음 크기</span><input id="titleSfxVolume" type="range" min="0" max="100" value="${Math.round(s.volume*100)}"></label><label class="title-option"><span>대사 글자 속도</span><select id="titleVnSpeed"><option value="30" ${s.vnSpeed===30?'selected':''}>보통</option><option value="12" ${s.vnSpeed===12?'selected':''}>빠르게</option><option value="0" ${s.vnSpeed===0?'selected':''}>즉시</option></select></label><label class="title-option"><span>움직임 줄이기</span><input id="titleReduceMotion" type="checkbox" ${s.reduceMotion?'checked':''}></label><p class="music-credit">게임 BGM: <a href="https://incompetech.com/music/royalty-free/index.html?isrc=USUAN1700069" target="_blank" rel="noopener noreferrer">Bossa Antigua — Kevin MacLeod (incompetech.com)</a><br><a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">Creative Commons: By Attribution 4.0 License</a> · 원본 음원, 반복 재생</p>`);
  $('#titleBgmEnabled').onchange=e=>{settings.music=e.target.checked;persistSettings();setBlocked()};$('#titleBgmVolume').oninput=e=>{settings.musicVolume=Number(e.target.value)/100;persistSettings();playMusic()};
  $('#titleSfxEnabled').onchange=e=>api.preference('sound',e.target.checked);$('#titleSfxVolume').oninput=e=>{api.preference('volume',Number(e.target.value)/100);api.beep('cup')};$('#titleVnSpeed').onchange=e=>api.preference('vnSpeed',Number(e.target.value));$('#titleReduceMotion').onchange=e=>api.preference('reduceMotion',e.target.checked);
 }
 async function enter(fresh){if(!ready){if(!await prepare())return}inSession=true;panel=null;visible=false;$('#titlePanel').hidden=true;setBlocked();if(fresh)api.newGame();else api.continueGame()}
 function home(){api.pause();api.save();api.stopMusic();visible=true;panel=null;$('#titlePanel').hidden=true;setBlocked();$('#titleScreen [data-title-action="continue"]').disabled=!api.hasProgress();$('#titleScreen [data-title-action="start"]').focus()}
 function open(kind='menu'){
  if(kind==='save'||kind==='load'){slotView(kind);return}if(kind==='settings'){showSettings();return}
  showPanel('menu','게임 메뉴','<div class="pause-options"><button data-pause="resume" class="primary">계속하기</button><button data-pause="save">저장</button><button data-pause="load">불러오기</button><button data-pause="settings">설정</button><button data-pause="home">타이틀로</button></div>');
  document.querySelectorAll('[data-pause]').forEach(b=>b.onclick=()=>{const action=b.dataset.pause;if(action==='resume')closePanel();else if(action==='home')home();else open(action)});
 }
 function mount(value){
  audio.id='titleAudio';audio.hidden=true;$('#titleScreen').appendChild(audio);gameAudio.id='cafeAudio';gameAudio.hidden=true;document.body.appendChild(gameAudio);audio.addEventListener('playing',()=>{const hint=$('#titleMusicHint');if(hint)hint.hidden=true});api=value;store=new RingSaveSlots(localStorage,api.validate);visible=true;setBlocked();
  document.querySelectorAll('[data-title-action]').forEach(button=>button.onclick=()=>{api.beep();const action=button.dataset.titleAction;if(action==='start'){if(api.hasProgress())confirmAction('처음부터 시작','새 게임을 시작할까요? 자동 저장은 새 진행으로 바뀌며, 5개의 수동 저장 슬롯은 그대로 남습니다.',()=>enter(true));else enter(true)}else if(action==='continue')enter(false);else if(action==='save'||action==='load')slotView(action);else if(action==='settings')showSettings();else if(action==='exit'){const stored=api.save();audio.pause();showPanel('exit','플레이를 마쳤어요.',(stored?'<p class="title-confirm-copy">현재 진행은 자동 저장되었습니다. 이 탭을 닫아도 됩니다.</p>':'<p class="title-confirm-copy">진행을 저장하지 못했습니다. 브라우저 저장 설정을 확인한 뒤 다시 시도해 주세요.</p>')+'<button id="exitBack" class="primary">타이틀로 돌아가기</button>');audio.pause();$('#exitBack').onclick=()=>{closePanel();playMusic()}}});
  $('#titleMusic').onclick=()=>{settings.music=!settings.music;persistSettings();setBlocked()};$('#titleRetry').onclick=prepare;
  document.addEventListener('pointerdown',()=>{if(panel!=='exit')playMusic()},{capture:true,passive:true});document.addEventListener('keydown',event=>{if(panel!=='exit')playMusic();if(!visible&&!panel)return;if(event.key==='Escape'){if(panel){event.preventDefault();closePanel()}return}if(event.key==='Tab'){const host=panel?$('#titlePanel'):$('#titleScreen');const nodes=[...host.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled])')].filter(node=>!node.hidden);if(!nodes.length)return;const at=nodes.indexOf(document.activeElement);if(at<0||event.shiftKey&&at===0||!event.shiftKey&&at===nodes.length-1){event.preventDefault();nodes[event.shiftKey?nodes.length-1:0].focus()}}});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){audio.pause();gameAudio.pause()}else if(panel!=='exit')playMusic()});
  let resume=false;try{resume=sessionStorage.getItem('project-ring-resume-once')==='yes';sessionStorage.removeItem('project-ring-resume-once')}catch{}
  prepare().then(ok=>{if(ok&&resume)enter(false)});
 }
 function finishLoad(){visible=false;panel=null;inSession=true;$('#titlePanel').hidden=true;setBlocked()}
 return {mount,open,home,finishLoad,get blocked(){return visible||!!panel},get visible(){return visible},get inSession(){return inSession}};
})();
